import { Component, createMemo, For, Show } from "solid-js";

import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { Divider } from "#core/ui-next/components/divider.jsx";
import { PortraitIcon } from "#core/ui-next/components/portrait-icon.jsx";
import { HSlot } from "#core/ui-next/components/slot.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import { VictoryRowPlayer } from "#base/ui-next/screens/victories/victories-screen-model.js";
import { VictoryCountdownTooltip } from "#base/ui-next/tooltips/victory-countdown-tooltip.jsx";

import style from "#base/ui-next/screens/victories/victories-screen.scss?url";

export interface VictoryCountdownPlayer {
	playerInfo: VictoryRowPlayer;
	countdownProgress: number;
	launchpadDamaged: boolean;
}
export interface VictoryCountdownBarProps {
	players: VictoryCountdownPlayer[];
	countdownDuration: number;
}
const VictoryCountdownBarComponent: Component<VictoryCountdownBarProps> = (props) => {
	const playersByIndex = createMemo<Record<number, VictoryCountdownPlayer[]>>(() => {
		const playersByIndexDictionary: Record<number, VictoryCountdownPlayer[]> = {};
		for (let i = 0; i < props.countdownDuration; i++) {
			playersByIndexDictionary[i] = [];
		}

		props.players.forEach((player) => {
			const index = player.countdownProgress;

			if (playersByIndexDictionary[index]) {
				playersByIndexDictionary[index].push(player);
			} else {
				console.warn("Invalid countdownProgress:", index, player);
			}
		});

		return playersByIndexDictionary;
	});

	const furthestProgress = createMemo<number>(() => {
		if (props.players.length === 0) {
			return 0;
		}

		return props.players.reduce((max, player) => Math.max(max, player.countdownProgress), 0);
	});

	const barWidthAsPercent = createMemo(() => {
		const total = props.countdownDuration;
		const progress = furthestProgress();

		if (total <= 0 || progress <= 0) {
			return "0%";
		}

		const percentage = (progress / total) * 100;
		return `${Math.min(percentage, 100)}%`;
	});

	function peekPortraits(event: Event) {
		const el = event.currentTarget as HTMLDivElement;
		const numChildren = el.childNodes.length;
		const step = 180 / numChildren;
		el.childNodes.forEach((child, index) => {
			const childElement = child as HTMLDivElement;
			if (!childElement) {
				return;
			}
			childElement.classList.add("expand");

			const angle = 180 + (step * index + step / 2);
			const angleInRads = (angle / 360) * Math.PI * 2;
			const xDistance = 10 * numChildren;
			const yDistance = 20;
			childElement.style.setProperty("--x", `${Math.cos(angleInRads) * xDistance}px`);
			childElement.style.setProperty("--y", `${Math.sin(angleInRads) * yDistance}px`);
		});
	}

	function unpeekPortraits(event: Event) {
		const el = event.currentTarget as HTMLDivElement;
		el.childNodes.forEach((child) => {
			const childElement = child as HTMLDivElement;
			if (!childElement) {
				return;
			}
			childElement.classList.remove("expand");
		});
	}

	return (
		<HSlot
			class="h-4 w-128 items-center justify-center relative"
			style={{
				"background-image":
					"linear-gradient(to right, rgba(51, 54, 64, 1), rgba(51, 54, 64, 0.75), rgba(51, 54, 64, 1))",
			}}
		>
			<div
				class="absolute left-0 h-full"
				style={{
					width: barWidthAsPercent(),
					"background-image": "linear-gradient(to left, rgba(87, 149, 68, 1), rgba(13, 73, 32, 1))",
					"border-color": "rgba(140, 126, 98, 1)",
					"border-style": "solid",
					"border-width": "1px",
				}}
			/>
			<For each={Array.from({ length: props.countdownDuration })}>
				{(_, index) => {
					const players = createMemo(() => playersByIndex()[index()]);
					return (
						<div class="relative flex-auto flex flex-col justify-center">
							<Divider.Vertical class="-translate-x-1\/2" />
							<Show when={index() > 0 && players() && players().length > 0}>
								<Show
									when={players().length > 1}
									fallback={
										<VictoryCountdownTooltip
											countdownDuration={props.countdownDuration}
											players={players()}
										>
											<div class="absolute -translate-x-1\/2">
												<PortraitIcon
													size={12}
													playerId={players()[0].playerInfo.playerId}
													desaturate={players()[0].launchpadDamaged}
												/>
											</div>
										</VictoryCountdownTooltip>
									}
								>
									<VictoryCountdownTooltip
										countdownDuration={props.countdownDuration}
										players={players()}
									>
										<Activatable
											class="absolute size-12 left-0 -translate-x-1\/2"
											onMouseOver={(e) => peekPortraits(e)}
											onFocusIn={(e) => peekPortraits(e)}
											onMouseOut={(e) => unpeekPortraits(e)}
											onFocusOut={(e) => unpeekPortraits(e)}
										>
											<For each={players()}>
												{(player, index) => (
													<div
														class="countdown-bar-portrait absolute"
														style={{
															"--initial-left": `${(index() / players().length) * 16 - 8}px`,
														}}
													>
														<PortraitIcon
															size={12}
															playerId={player.playerInfo.playerId}
															desaturate={player.launchpadDamaged}
														/>
													</div>
												)}
											</For>
										</Activatable>
									</VictoryCountdownTooltip>
								</Show>
							</Show>
						</div>
					);
				}}
			</For>
			<Divider.Vertical class="translate-x-1\/2" />
		</HSlot>
	);
};

export const VictoryCountdownBar = ComponentRegistry.register({
	name: "VictoryCountdownBar",
	createInstance: VictoryCountdownBarComponent,
	styles: [style],
});
